function validate(input) {
  const [{ Activity = [] }] = input;
  const kinds = ['open_session', 'end_session', 'scroll_down', 'send_message'];
  const owner = new Map();
  for (const [user, session, date, type] of Activity) {
    if (user === null || session === null || date === null || type === null) return 'Every column of Activity is required.';
    if (!kinds.includes(type)) return `Unknown activity_type ${type}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `activity_date ${date} is not YYYY-MM-DD.`;
    if (owner.has(session) && owner.get(session) !== user) return `Session ${session} belongs to two users.`;
    owner.set(session, user);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const kinds = ['open_session', 'end_session', 'scroll_down', 'send_message'];
  const day = offset => new Date(Date.UTC(2019, 5, 20 + offset)).toISOString().slice(0, 10);
  // Small dates sit on both edges of the window; large ones spread from 2019-06-20 to 2019-08-08.
  const edges = ['2019-06-26', '2019-06-27', '2019-06-28', '2019-07-05', '2019-07-26', '2019-07-27', '2019-07-28', '2019-08-02'];
  const users = small ? 4 : 300, sessions = small ? 6 : 700, rows = small ? pick(9) : 2000;
  const owner = [];
  for (let s = 1; s <= sessions; s++) owner[s] = 1 + pick(users);
  const Activity = [];
  for (let i = 0; i < rows; i++) {
    if (Activity.length && rand() < 0.15) { Activity.push([...Activity[pick(Activity.length)]]); continue; }
    const session = 1 + pick(sessions);
    Activity.push([owner[session], session, small ? edges[pick(edges.length)] : day(pick(50)), kinds[pick(kinds.length)]]);
  }
  // Keep the answer clear of a rounding tie at the third decimal, where float and MySQL decimal arithmetic could
  // disagree: each extra active user with one session changes the average.
  for (let extra = 1; extra < 20; extra++) {
    const active = Activity.filter(([, , date]) => date >= '2019-06-28' && date <= '2019-07-27');
    const people = new Set(active.map(row => row[0])).size, visits = new Set(active.map(row => row[1])).size;
    if (!people || Math.abs((visits / people * 100) % 1 - 0.5) > 0.01) break;
    Activity.push([users + extra, sessions + extra, '2019-07-15', 'open_session']);
  }
  return [{ Activity }];
}
